      "confianca_ficha": "media",
      "status_ficha": "curado",
      "descricao_o_que_e": "A tradição da Classical Political Economy assume como ponto de partida o processo social de produção, reprodução e distribuição. Ao contrário da abordagem individualista e marginalista posterior, a economia política clássica trata a economia como um sistema historicamente situado, onde mercado, Estado e ordem social operam de forma interdependente. Ela assume a existência de classes sociais distintas — proprietários de terra, capitalistas e trabalhadores — como unidades fundamentais na determinação das dinâmicas distributivas.\n\nO escopo analítico central do campo gira em torno da produção e apropriação do excedente social. A literatura formula os princípios fundamentais da divisão do trabalho, vantagem comparativa, preços naturais (preços de produção orientados pelo custo), renda da terra e dos limites demográficos e físicos ao crescimento. Ao articular esses temas, resolve o problema de criar um vocabulário capaz de descrever tanto a ordem e a coordenação espontânea (mão invisível) quanto os conflitos distributivos inerentes à expansão do capitalismo industrial emergente.\n\nA tradição explicitamente deixa de fora a modelagem do agente econômico como um otimizador puro de utilidade subjetiva sob restrições estritas de escassez (um foco da Literatura - Neoclassical Economics). Também não oferece microfundamentos axiomáticos para decisões eleitorais ou interações estratégicas formalizadas. Essas lacunas metodológicas em relação ao individualismo metodológico e à agregação formal são preenchidas por abordagens posteriores como a Literatura - Social Choice Theory e a Literatura - Game-Theoretic Political Economy.",
