      "confianca_ficha": "alta",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Political Science é a disciplina acadêmica que toma o poder político como objeto próprio: quem governa, como governa, por quais instituições e com quais formas de legitimidade. No mapa, ela aparece apenas como tronco-fonte de linhagens que entram na Economia Política, não como tentativa de mapear a ciência política inteira.\n\nA função genealógica do nó é ancorar a parte politológica da Economia Política: comparative political economy, historical institutionalism, estudos de regimes, democratização, backsliding e política não democrática. Essas literaturas importam conceitos como Estado, regime, burocracia, partido, representação e legitimidade, que não derivam apenas da economia.\n\nO que fica fora é deliberado: teoria política normativa, relações internacionais em sentido amplo, segurança, administração pública e vários debates internos da disciplina só entram se virarem ponte substantiva com Economia Política.",
