      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Sociology é a disciplina que trata estruturas sociais, autoridade, estratificação, cultura, instituições e ação coletiva como fenômenos explicativos próprios. No mapa, ela não representa a sociologia inteira; funciona como tronco-fonte das linhagens sociológicas que atravessam a Economia Política.\n\nA ponte central é a ideia de que a economia está embutida em relações sociais, instituições e ordens de status. Por isso, a sociologia ancora contribuições que aparecem em moral economy, dependência, world-systems, Polanyi, Bourdieu, capital social, instituições e cultura política.\n\nO nó fica no tronco neutro porque essas contribuições antecedem e cruzam várias famílias visuais. Pintá-lo como marxista, clássico ou comparativo faria a disciplina parecer filha de uma tradição que, na genealogia do mapa, ela também ajuda a formar.",
