      "confianca_ficha": "media",
      "status_ficha": "curado",
      "descricao_o_que_e": "A tradição de Marxist and Historical Political Economy assume que sistemas econômicos não são constructos universais, mas modos de produção e configurações institucionais historicamente específicos. Em vez de tomar preferências individuais e instituições como dadas ou exógenas, a área pergunta como essas estruturas emergem de dinâmicas de poder, relações de propriedade, dominação de classe e trajetórias evolutivas de longo prazo, entendendo o capitalismo e o Estado como produtos de processos históricos contínuos.\n\nA sua contribuição central é deslocar a economia política para a análise estrutural e macro-sociológica, resolvendo questões sobre as origens das instituições, o desenvolvimento econômico, a acumulação de capital e o conflito distributivo. O campo investiga desde a teoria do valor, exploração e crise (no marxismo clássico), passando pelas raízes do desenvolvimento e da dependência global (sistemas-mundo), até a persistência institucional e a inferência causal histórica (na contemporânea Historical Political Economy), mapeando como o passado sedimenta as capacidades estatais e as desigualdades presentes.\n\nExplicitamente, esta tradição resiste a reduzir a política e a economia à simples escolha individual otimizadora abstraída do tempo e do espaço. Por não focar primariamente na construção de microfundamentos isolados ou no desenho de equilíbrios de jogos estáticos para interação estratégica de curto prazo, ela delega a formalização de incentivos e agregação abstrata para a Literatura - Neoclassical Economics, a Literatura - Public Choice e a Literatura - Game-Theoretic Political Economy.",
