      "confianca_ficha": "alta",
      "status_ficha": "curado",
      "descricao_o_que_e": "A Game-Theoretic Political Economy é um programa de pesquisa que utiliza a teoria dos jogos e a economia formal para estudar a política como um campo de interações estratégicas. Assume como dados a racionalidade dos agentes políticos (eleitores, legisladores, lobistas, governantes) e as regras institucionais sob as quais operam, buscando entender como esses atores maximizam seus objetivos condicionados às respostas esperadas dos demais.\n\nSeu principal escopo é resolver problemas políticos complexos ao traduzi-los em modelos de equilíbrio: como eleições disciplinam agentes (accountability eleitoral), como agendas são formadas no legislativo (barganha de Baron-Ferejohn), e como grupos de pressão influenciam políticas (common agency e lobby de Grossman-Helpman). A área examina sistematicamente o efeito do compromisso institucional e da assimetria informacional sobre os resultados, consolidando conceitos como o Markov Perfect Equilibrium para descrever dinâmicas políticas de longo prazo.\n\nExplicitamente, a literatura deixa de fora a formação profunda e cultural das preferências ou identidades dos agentes, tema que é coberto pela Literatura - Behavioral and Cultural Political Economy. Além disso, enquanto modela transições políticas dadas certas distribuições de poder, frequentemente abstrai as causas estruturais históricas mais longas que formaram essas distribuições, sendo complementada pela análise da Literatura - Historical Political Economy e da Literatura - Comparative Political Economy.",
      "ancoragem_base": 2.1,
