      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Malthusianism parte da tensao entre crescimento populacional, recursos naturais, produtividade, salarios, pobreza e limites ao crescimento. O DR ancora a linha em Malthus (1798), *An Essay on the Principle of Population*, e lembra que Malthus tambem escreveu sobre demanda efetiva, renda, poupanca, crise e excesso geral de oferta.\n\nMalthus (1820), *Principles of Political Economy*, permite ligar a tradicao aos debates sobre demanda efetiva e leituras keynesianas, enquanto Zarikos (2025), \"Malthus in the Anthropocene\", mostra a retomada recente em clima e limites planetarios. A ficha fica como linha porque o DR diz que nao ha uma escola unificada, mas ha uma fronteira viva em demografia historica, unified growth, Estado, conflito e ecologia.",
