      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Neo-Ricardianism, Sraffianism, and the Classical-Keynesian Tradition reconstroi a abordagem classica no seculo XX a partir de precos de producao, insumos produzidos, excedente e distribuicao, sem depender da produtividade marginal dos fatores. O DR ancora a tradicao em Sraffa (1960), *Production of Commodities by Means of Commodities*, e em Sraffa (1926), \"The Laws of Returns under Competitive Conditions\".\n\nA tradicao posterior inclui Pasinetti, Garegnani, Bharadwaj, Roncaglia, Kurz, Salvadori e Steedman, com Martins (2022), \"Sraffian Political Economy\", como sintese recente. A ficha fica como tradicao porque o DR a apresenta como escola ativa em teoria de precos, capital, distribuicao, critica ao marginalismo, crescimento liderado pela demanda, supermultiplicador e Cambridge capital controversies.",
