      "descricao_o_que_e": "German Historical School e a tradicao que rejeitou leis economicas universais e abstratas, defendendo que a economia deve estudar instituicoes, nacoes, costumes, direito, historia e estagios de desenvolvimento. Sua relacao com a Classical Political Economy e de oposicao constitutiva: Roscher, List e depois Schmoller reagem ao universalismo abstrato associado a Ricardo e Mill, mas herdam dele o universo de problemas que passam a historicizar.\n\nRoscher (1843) e Schmoller (1900-1904) completam a genealogia da escola historica no DR, inclusive pelo debate metodologico contra abstracao universalista. A ficha fica sob o guarda-chuva Marxist and Historical Political Economy por afinidade historico-institucional, mas nao descende dele cronologicamente: a escola historica alema antecede Marx 1867 e e um dos insumos desse bloco historico mais amplo.",
