      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Marxian Value Exploitation Accumulation and Crisis e a linha que aprofunda a teoria economica de Marx sobre valor, precos de producao, mais-valia, reproducao do capital, lucro, credito, financeirizacao e dinamica de crise. O DR ancora essa linha em *Capital* (Marx 1867-1894), especialmente como matriz para tratar valor, exploracao e acumulacao como formas historicas do capitalismo.\n\nLuxemburg (1913), *The Accumulation of Capital*, Hilferding (1910), *Finance Capital*, e Foley (1982), \"The Value of Money, the Value of Labor Power and the Marxian Transformation Problem\", aparecem como referencias de extensao e disputa interna. A ficha fica como linha porque o DR a apresenta como aprofundamento economico da raiz marxista, com forte dialogo com macroeconomia politica, pos-keynesianos e sraffianos.",
      "ancoragem_base": -2.2,
      "ancoragem_analitica_auto": -1.673,
      "ancoragem_analitica": -2
