      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Old American Institutionalism, associado a Veblen, Commons e Mitchell, criticou o individualismo abstrato e enfatizou habitos, instituicoes, evolucao, direito, conflito, tecnologia e mudanca historica. O DR ancora a tradicao em Veblen (1899), *The Theory of the Leisure Class*, como obra seminal sobre status, consumo conspicuo e formacao social de preferencias.\n\nCommons (1934), *Institutional Economics*, e Mitchell (1913), *Business Cycles*, aparecem no DR como referencias para transacoes, direito, governanca e ciclos. A ficha fica como tradicao porque o DR a descreve como escola autonoma menos ativa, mas influente em evolutionary economics, law and economics institucionalista, behavioral economics heterodoxa e sociologia economica.",
