      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Monopoly Capital Imperialism Dependency and World-Systems desloca a analise marxista para escalas internacionais e globais: imperialismo, centro-periferia, dependencia, troca desigual, capital financeiro, colonialismo e divisao internacional do trabalho. O DR apresenta Lenin (1917), *Imperialism, the Highest Stage of Capitalism*, como peca classica dessa familia.\n\nBaran e Sweezy (1966), *Monopoly Capital*, Frank (1966), \"The Development of Underdevelopment\", e Wallerstein (1974), *The Modern World-System I*, aparecem no DR como obras seminais de capital monopolista, dependencia e sistemas-mundo. A ficha funde essas correntes porque o DR as organiza na mesma subtradicao global, com debates compartilhados sobre desenvolvimento, colonialismo, hegemonia e persistencia historica.",
