      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Moral Economy / Moral Political Economy analisa como obrigacoes morais, legitimidade, justica substantiva, subsistencia, trabalho, migracao, compaixao, repressao e mercados moralmente enquadrados moldam conflitos economicos e politicos. A literatura atravessa historia social, antropologia, sociologia economica, teoria politica, regulacao e welfare state.\n\nThompson (1971), \"The Moral Economy of the English Crowd in the Eighteenth Century\", e apresentado no DR como marco da economia moral classica, mostrando que revoltas de alimento seguiam expectativas normativas sobre preco justo e subsistencia. O DR tambem destaca Scott (1976), Fassin (2009), Hann (2018) e Sayer (2000/2007) como expansoes da agenda.",
