      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Peasant Moral Economy e a linha classica sobre subsistencia, seguranca, obrigacoes comunitarias e legitimidade em sociedades camponesas. Ela interpreta rebelioes, resistencia e conflito rural nao como irracionalidade, mas como resposta a violacoes de expectativas morais sobre sobrevivencia, protecao e justica economica.\n\nScott (1976), *The Moral Economy of the Peasant: Rebellion and Subsistence in Southeast Asia*, e citado no DR como marco da economia moral camponesa. O proprio DR observa que essa sublinha classica continua fundamental como referencia, embora esteja hoje mais historica e parcialmente dormente do que no centro cumulativo da agenda contemporanea.",
