      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Regulation Theory and Social Structures of Accumulation analisa o capitalismo como sucessao de regimes historicos sustentados por instituicoes, normas salariais, concorrencia, Estado, moeda, relacoes internacionais e padroes de demanda. O DR ancora a vertente francesa em Aglietta (1979 [1976]), *A Theory of Capitalist Regulation: The US Experience*.\n\nA abordagem SSA aparece no DR por Gordon, Edwards e Reich (1982), *Segmented Work, Divided Workers*, e Kotz, McDonough e Reich (1994), *Social Structures of Accumulation*. A ficha funde regulacao e SSA porque o DR as trata conjuntamente como subarea de regimes de acumulacao, crises institucionais, Fordismo, pos-Fordismo, neoliberalismo e financeirizacao.",
