      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Walrasian General Equilibrium formula a economia como um sistema simultaneo de mercados interdependentes e pergunta se existem precos que compatibilizam todos os planos individuais. O DR ancora a tradicao em Walras (1874-1877), *Elements of Pure Economics*, e na versao moderna de Arrow e Debreu (1954), \"Existence of an Equilibrium for a Competitive Economy\".\n\nDebreu (1959), *Theory of Value*, torna o programa axiomatico e liga existencia de equilibrio a teoremas do bem-estar, mercados completos, incerteza, estabilidade e producao. A ficha fica como subarea porque o DR apresenta o equilibrio geral como fundamento neoclassico ainda ativo em nichos tecnicos, financas, incomplete markets, CGE, asset pricing e economia matematica.",
