      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Marshallian Economics and Partial Equilibrium e a linha que consolidou oferta e demanda, equilibrio parcial, excedentes, elasticidade, custo marginal e distincao entre curto e longo periodo. O DR ancora a linha em Marshall (1890), *Principles of Economics*, como a obra que tornou mercados isolados analisaveis mantendo outros mercados constantes.\n\nO DR liga a descendencia marshalliana a microeconomia aplicada, organizacao industrial, economia do trabalho, comercio aplicado, public finance e incidencia tributaria. A ficha fica como linha porque o DR descreve a tradicao marshalliana como menos pura que a walrasiana, mas ainda viva no raciocinio empirico e setorial da micro aplicada.",
