      "descricao_o_que_e": "Computable General Equilibrium Models simulam efeitos de politicas em sistemas multissetoriais interdependentes, parametrizando uma economia walrasiana para avaliar comercio, impostos, energia, agua, clima e politicas setoriais. O DR ancora a linha em Scarf (1967) e Shoven e Whalley (1984), apresentados como obras seminais de equilibrio geral computavel.\n\nA ficha fica como linha porque o DR a apresenta como aplicacao ativa de equilibrio geral, especialmente em clima, energia, agua, comercio, tributacao e pandemias. Bryant (2025), *Handbook of Economy-Wide Microeconomics*, aparece no DR como referencia recente que revisita existencia, unicidade, estabilidade, otimalidade, CGE e testes de equilibrio.",
