      "descricao_o_que_e": "Information Economics and Contract Theory estuda como informacao privada, incentivos, sinalizacao, selecao adversa, moral hazard, contratos e regras de jogo afetam eficiencia e alocacao. O DR ancora a subarea em Akerlof (1970), \"The Market for Lemons\", Spence (1973), \"Job Market Signaling\", Rothschild e Stiglitz (1976), e Myerson (1981), \"Optimal Auction Design\".\n\nA ficha fica separada de Literatura - Mechanism Design porque a ficha existente ja cobre desenho de mecanismos como tradicao formal, enquanto esta seed captura a virada neoclassica mais ampla para informacao imperfeita e contratos. O DR descreve a linha como muito ativa e de fronteira em market design, auctions, matching, contract theory e politica publica.",
