      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Axiomatic Social Choice Theory e a linha transversal que caracteriza regras coletivas por propriedades formais interpretaveis: anonimato, neutralidade, Pareto, monotonicidade, independence of irrelevant alternatives, consistency, strategy-proofness e participation. O DR ancora essa meta-teoria em May (1952), \"A Set of Independent Necessary and Sufficient Conditions for Simple Majority Decision\", que caracteriza axiomaticamente a regra de maioria simples.\n\nPlott (1976), \"Axiomatic Social Choice Theory: An Overview and Interpretation\", organiza a interpretacao do metodo axiomatico, enquanto d'Aspremont e Gevers (1977) conectam axiomas a equidade e base informacional. A ficha fica separada da raiz porque nao e uma aplicacao substantiva, mas uma camada meta-metodologica que atravessa voting, welfare, judgment aggregation, fair division e computational social choice.",
