      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Investiga quando a escolha preferida de um eleitor mediano vence as alternativas em comparações por maioria. Em Black, preferências de pico único permitem ordenar os pontos ideais e identificar esse resultado. A condição de single crossing oferece outra via, baseada na ordenação dos tipos de eleitores; não é sinônimo de pico único. A convergência de dois candidatos requer hipóteses eleitorais adicionais. Romer e Meltzer–Richard aplicam argumentos de votação majoritária à tributação, distinguindo o teorema de agregação das escolhas econômicas que determinam preferências por impostos.",
