      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Probabilistic Social Choice and Random Assignment e a subarea que usa loterias sobre alternativas, objetos ou alocacoes para recuperar propriedades que regras deterministicas nao conseguem satisfazer. O DR identifica Fishburn (1972), \"Lotteries and Social Choices\", e Gibbard (1977), \"Manipulation of Schemes that Mix Voting with Chance\", como textos fundacionais para votacao com chance e manipulabilidade de regras randomizadas.\n\nBogomolnaia e Moulin (2001), \"A New Solution to the Random Assignment Problem\", deslocam a agenda para random assignment ordinal com eficiencia e fairness, enquanto Aziz (2019) sintetiza aplicacoes em votacao, alocacao, matching e formacao de coalizoes. A ficha funde probabilistic social choice e random assignment porque o DR os apresenta como uma mesma subtradicao, evitando duas seeds com o mesmo nucleo de loterias e stochastic dominance.",
      "ancoragem_base": 2.1,
      "ancoragem_analitica_auto": 1.888,
      "ancoragem_analitica": 2
