      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Social Choice under Risk and Uncertainty pergunta como avaliar socialmente alternativas quando resultados sao incertos, riscos sao distribuidos entre individuos ou agentes tem crencas subjetivas diferentes. O DR usa Hylland e Zeckhauser (1979), \"The Impossibility of Bayesian Group Decision Making with Separate Aggregation of Beliefs and Values\", como paper canonico para a impossibilidade de agregar separadamente crencas e valores.\n\nDiamond (1967) aparece no DR como critica ao utilitarismo de Harsanyi, e Mongin e Pivato (2016), \"Social Evaluation under Risk and Uncertainty\", como organizacao recente da agenda. A ficha fica separada de Welfare Social Choice porque seu problema central e a tensao ex ante vs. ex post, e nao apenas a construcao geral de uma funcao de bem-estar social.",
      "ancoragem_base": 2.1,
      "ancoragem_analitica_auto": 1.921,
