      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Judgment Aggregation estuda como transformar julgamentos individuais sobre proposicoes logicamente conectadas em um julgamento coletivo coerente. O DR apresenta Kornhauser e Sager (1986), \"Unpacking the Court\", como texto seminal para o paradoxo doutrinario: decisoes coletivas podem ser inconsistentes dependendo de se agregam premissas ou conclusoes.\n\nList e Pettit (2002), \"Aggregating Sets of Judgments: An Impossibility Result\", fazem da linha uma subliteratura explicita de social choice ao mostrar uma impossibilidade propria para agendas proposicionais. A ficha fica separada de Voting Theory porque aqui o input nao e apenas ranking ou voto sobre alternativas, mas conjuntos de crencas, razoes, premissas e conclusoes.",
      "ancoragem_base": 2.1,
