      "descricao_o_que_e": "Behavioral Social Choice testa empiricamente como pessoas entendem, usam e avaliam regras de votacao e procedimentos de escolha coletiva. A linha conecta axiomatica de social choice a psicologia, experimentos, modelos probabilisticos de preferencia e desenho institucional.\n\nO DR de Social Choice lista Regenwetter et al. (2009), \"Behavioral Social Choice: A Status Report\", como referencia central, junto do livro de Regenwetter, Grofman, Marley e Tsetlin (2006). A agenda recente aparece em Baujard et al. (2025), \"How People Understand Voting Rules\", sobre compreensao experimental de regras como evaluative voting e majority judgment.",
