      "descricao_o_que_e": "Estrutura de contratação em que vários principais procuram influenciar a ação de um mesmo agente. Em modelos de menu auctions, cada principal oferece pagamentos condicionados à decisão do agente. É uma ferramenta para estudar lobby e coordenação entre grupos. Resultados de eficiência dependem das hipóteses de informação, preferências e equilíbrio; não implicam, por si, eficiência para toda a sociedade nem ausência de distorções políticas.",
