      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Agenda Setting and Status Quo Politics e a linha de bargaining e social choice aplicado que pergunta como controle da agenda, sequencia de propostas e localizacao do status quo selecionam resultados politicos. O DR identifica Romer e Rosenthal (1978), \"Political Resource Allocation, Controlled Agendas, and the Status Quo\", como paper canonico porque mostra que o agenda setter pode deslocar politicas mesmo sob regra majoritaria.\n\nAusten-Smith e Banks (1988) conectam eleicoes, coalizoes e resultados legislativos, enquanto Baron e Ferejohn (1989) dao o modelo sequencial de barganha legislativa ao qual esta linha se acopla. Carpenter (2023), \"Agenda Democracy\", aparece no DR como fronteira recente, ampliando agenda control para uma teoria democratica da inclusao e exclusao de alternativas politicas.",
      "ancoragem_base": 2.1,
      "ancoragem_analitica_auto": 1.782,
      "ancoragem_analitica": 2
