      "confianca_ficha": "alta",
      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Modela como legisladores negociam a distribuição de recursos e a escolha de políticas. Em Baron e Ferejohn, parlamentares fazem propostas e votam considerando as oportunidades de negociação futura. As regras de reconhecimento de proponentes, emenda e aprovação afetam as coalizões e a distribuição resultante. A agenda passa a ser parte do jogo, em vez de uma lista de alternativas dada de antemão. A literatura conecta barganha e instituições legislativas; disciplina partidária, poderes de veto e múltiplas dimensões de política exigem extensões do modelo básico.",
