      "descricao_o_que_e": "Informational Lobbying e a linha que modela lobby como transmissao estrategica de informacao, expertise, sinais e acesso, em contraste com lobby entendido apenas como compra de influencia ou contribuicao eleitoral. O DR destaca Austen-Smith (1993), \"Information and Influence: Lobbying for Agendas and Votes\", como paper canonico dessa mudanca de mecanismo.\n\nBecker (1983) fornece a base de competicao entre grupos de pressao, mas aqui a pergunta central e quando informacao de grupos organizados melhora decisao publica e quando vira captura, vies ou manipulacao da agenda. Schnakenberg e Turner (2024) e Garlick, Junk e Brown (2025) aparecem no DR como surveys recentes que conectam essa familia a formal theories of special interest influence e evidencia contemporanea sobre lobby.",
