      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Reform Delay and Policy Inefficiency e a linha que usa jogos dinamicos, compromisso intertemporal e conflito distributivo para explicar por que reformas desejaveis atrasam ou por que politicas ineficientes persistem. O DR ancora a linha em Alesina e Drazen (1991), \"Why Are Stabilizations Delayed?\", que usa um modelo de war of attrition para explicar atraso de estabilizacoes macroeconomicas.\n\nAcemoglu (2005), \"Politics and Economics in Weak and Strong States\", e Acemoglu, Ticchi e Vindigni (2011), \"Emergence and Persistence of Inefficient States\", ampliam o mecanismo para estados fracos, estados fortes demais e burocracias ineficientes como escolhas politicas. Heo e Wirsching (2026) aparece no DR como exemplo recente de resistencia burocratica e ineficiencia de politica, mantendo a linha conectada a state capacity e governanca.",
