      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Political Economy of Mass Media e a subarea que trata imprensa, televisao, plataformas e propaganda como atores estrategicos dentro de mercados de informacao politica. O DR ancora a linha em Besley e Prat (2006), \"Handcuffs for the Grabbing Hand? Media Capture and Government Accountability\", que modela media capture como um mecanismo que enfraquece accountability eleitoral.\n\nGentzkow e Shapiro (2006), \"Media Bias and Reputation\", deslocam a analise para reputacao, crencas dos consumidores e incentivos dos veiculos, enquanto Prat e Stromberg (2013), \"The Political Economy of Mass Media\", organizam a literatura como agenda propria. A seed fica separada de Political Agency porque o foco aqui nao e apenas o eleitor monitorando politicos, mas o sistema informacional que seleciona, distorce ou bloqueia sinais politicos.",
