      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Estuda o enfraquecimento de instituições democráticas por governantes, partidos e seus apoiadores, incluindo redução de controles sobre o Executivo e manipulação da competição eleitoral. Svolik analisa como o conflito partidário pode tornar custoso punir um governante que viola normas democráticas. Graham e Svolik investigam esses dilemas entre eleitores nos Estados Unidos; Bermeo distingue formas de retrocesso e mudanças em sua frequência. Polarização, informação e instituições afetam esses processos, e o retrocesso gradual deve ser distinguido de golpes militares e outras rupturas.",
      "ancoragem_base": -1.1,
