      "descricao_o_que_e": "Estuda como grupos organizados influenciam políticas, participam de eleições e disputam acesso a decisores. Grossman e Helpman distinguem influência por informação, contribuições para campanhas e incentivos oferecidos aos governantes. Modelos de agência comum formalizam o caso em que vários grupos propõem pagamentos condicionados às decisões de um mesmo agente público; Protection for Sale aplica essa estrutura à política comercial. A organização dos grupos, seus interesses e as regras institucionais ajudam a explicar quem obtém influência e como ela altera a distribuição de recursos.",
