      "descricao_o_que_e": "Estuda como grupos de interesse influenciam decisões públicas por contribuições condicionadas às políticas escolhidas. Nos modelos de agência comum, vários principais oferecem ao mesmo decisor esquemas de pagamento; o governo combina contribuições e bem-estar em seu objetivo. Menu auctions ajudam a analisar a coordenação entre grupos e as distorções na escolha de políticas. Resultados de eficiência dependem das hipóteses de informação, transferibilidade e equilíbrio. Esse mecanismo de contribuições não cobre, por si só, o lobby informacional ou todas as formas de influência política.",
