      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Polycentric Governance and Commons é a tradição que conecta Public Choice e New Institutional Economics à Bloomington School, estudando arranjos com múltiplos centros de decisão, regras locais e governança de recursos comuns. No DR de NIE, Ostrom, Walker e Gardner (1992), \"Covenants with and without a Sword\", é a referência experimental que mostra como comunicação, compromisso e sanções podem sustentar cooperação sem depender apenas de mercado ou Estado centralizado.\n\nOstrom (2000), \"Collective Action and the Evolution of Social Norms\", e Ostrom (2010), \"Beyond Markets and States\", consolidam a passagem para normas, confiança, policentrismo e sistemas complexos de governança. A linha segue ativa no DR em governança ambiental, recursos comuns, clima, água, pesca, florestas, experimental economics, behavioral political economy e institutional analysis and development.",
