      "descricao_o_que_e": "Behavioral Public Choice / Behavioral Political Economy aplica racionalidade limitada, vieses cognitivos, heuristicas, framing e motivacoes nao padrao ao estudo de eleitores, politicos, burocratas, juizes, reguladores e grupos de interesse. A literatura corrige a assimetria em que agentes privados seriam enviesados, mas formuladores de politica apareceriam como planejadores racionais e benevolentes.\n\nO paper de Schnellenbach e Schubert (2015), \"Behavioral Political Economy: A Survey\", e mencionado no DR como referencia que da nome explicito ao campo em sentido moderno. A linha tambem inclui Brennan e Lomasky (1993) sobre preferencias eleitorais expressivas e Caplan (2002) sobre crencas economicamente enviesadas dos eleitores.",
