      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Agency Theory and Team Production é a linha da New Institutional Economics que pergunta como desenhar contratos, estruturas de propriedade e mecanismos de governança sob separação entre principal e agente, informação assimétrica, moral hazard, risco e conflito de interesse. Alchian e Demsetz (1972), \"Production, Information Costs, and Economic Organization\", é o paper canônico no DR para tratar a firma como resposta a problemas de produção em equipe, monitoramento e mensuração da contribuição individual.\n\nJensen e Meckling (1976), \"Theory of the Firm: Managerial Behavior, Agency Costs and Ownership Structure\", formalizam custos de agência e conectam teoria da firma, direitos de propriedade, finanças e governança corporativa. O DR classifica essa agenda como extremamente ativa fora da NIE, mas relativamente dormente como subtradição autônoma da NIE, pois foi absorvida por corporate finance, governance, accounting, law and economics e teoria contratual.",
      "ancoragem_base": -0.25,
      "ancoragem_analitica_auto": 0.026,
      "ancoragem_analitica": 1
