      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Incomplete Contracts and Residual Control é a linha que pergunta como alocar direitos de controle quando nem todas as contingências futuras podem ser especificadas, observadas, verificadas ou executadas por tribunais. Grossman e Hart (1986), \"The Costs and Benefits of Ownership\", é o paper fundador indicado no DR porque estabelece a abordagem moderna de direitos residuais de controle.\n\nHart e Moore (1990), \"Property Rights and the Nature of the Firm\", ampliam a teoria para propriedade e fronteiras da firma, enquanto Aghion e Bolton (1992) levam contratos incompletos para contratos financeiros. O DR trata a linha como ativa, mas com fronteira deslocada para contratos relacionais, repeated games, outsourcing, cadeias de suprimento, plataformas, direito contratual e evidência empírica de contratos reais.",
