      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Investiga como receitas de recursos naturais alteram extração, clientelismo e alocação de trabalho. Em Robinson, Torvik e Verdier (2006), booms de recursos afetam os incentivos do governante a permanecer no poder; o efeito agregado depende das instituições. A nota dos autores de 2014 apresenta um modelo reduzido que preserva os resultados e discute uma falha na especificação da utilidade do modelo original. Abundância de recursos não implica necessariamente pior desempenho: a literatura distingue mecanismos políticos, econômicos e institucionais.",
