      "descricao_o_que_e": "Examina como partidos, legislaturas e acordos entre elites organizam o poder sob autoritarismo. Instituições podem viabilizar cooptação, coordenação ou compromissos entre governantes e apoiadores, sem necessariamente impor limites efetivos ao líder. Gandhi enfatiza instituições sob ditadura; Magaloni analisa a partilha crível de poder; Svolik distingue conflitos entre elites dos problemas de controle da população. A estabilidade desses arranjos depende de ameaças de golpe, mobilização, informação e capacidade de compromisso. A mera existência de um parlamento não demonstra divisão efetiva do poder.",
