      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Power Resources and Welfare State Regimes e a subtradicao comparada que explica regimes de bem-estar por coalizoes de classe, organizacao do trabalho, partidos de esquerda, instituicoes politicas e feedbacks de politicas sociais. O DR ancora a linha em Korpi (1983), *The Democratic Class Struggle*, e Esping-Andersen (1990), *The Three Worlds of Welfare Capitalism*, como textos centrais para power resources e tipologias de welfare regimes.\n\nPierson (1996), \"The New Politics of the Welfare State\", desloca a discussao para retrenchment, veto players e grupos beneficiarios, enquanto Huber e Stephens (2001) conectam partidos, globalizacao e crise do welfare state. A ficha complementa a area geral de Redistribution and Welfare State Political Economy com a tradicao especificamente comparativa de welfare regimes e social democracy.",
