      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Ideas, Discourse and Knowledge Regimes e a subtradicao que explica como ideias economicas, paradigmas de politica, expertise e regimes de conhecimento moldam escolhas publicas e mudanca institucional. O DR ancora a linha em Hall (1989), *The Political Power of Economic Ideas*, e Hall (1993), \"Policy Paradigms, Social Learning, and the State\", como textos centrais para entender policy paradigms e aprendizado social.\n\nBlyth (1997), \"Any More Bright Ideas?\", nomeia a virada ideacional em CPE, enquanto Campbell e Pedersen (2015), \"Policy Ideas, Knowledge Regimes and Comparative Political Economy\", deslocam o foco para think tanks, universidades, orgaos tecnicos e redes de especialistas. A ficha dialoga com Behavioral and Cultural Political Economy, mas preserva a escala comparativa de instituicoes de expertise e discurso politico-economico.",
