      "descricao_o_que_e": "Skills, Asset Specificity and Social Policy Preferences e a linha de CPE que deriva preferencias por protecao social do risco associado a investimentos em habilidades especificas de setor, firma ou ocupacao. O DR ancora a linha em Iversen e Soskice (2001), \"An Asset Theory of Social Policy Preferences\", que desloca a explicacao de welfare preferences de renda para especificidade de ativos e risco no mercado de trabalho.\n\nEstevez-Abe, Iversen e Soskice (2001), \"Social Protection and the Formation of Skills\", conectam protecao social e sistemas de treinamento dentro de Varieties of Capitalism, enquanto Iversen (2005), *Capitalism, Democracy, and Welfare*, consolida a agenda. A ficha fica como linha dentro de VoC porque seu mecanismo e microfundacional, mas depende das complementaridades institucionais entre skills, welfare e mercados de trabalho.",
