      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Business Power and Tax Politics e a subarea de CPE que trata empresas como atores politicos com poder estrutural, poder instrumental, lobby, controle de investimento, expertise e vantagem em arenas de baixa saliencia. O DR ancora a linha em Swenson (2002), *Capitalists Against Markets*, e Mares (2003), *The Politics of Social Risk*, porque esses textos mostram que empresarios podem apoiar welfare, treinamento ou seguro quando essas politicas resolvem problemas de coordenacao ou risco.\n\nCulpepper (2010/2011), *Quiet Politics and Business Power*, formaliza a importancia de baixa saliencia e arenas tecnicas para influencia empresarial, enquanto Fairfield (2015), *Private Wealth and Public Revenue in Latin America*, leva o tema para tax politics e poder de elites economicas. A ficha se conecta a Special Interest Politics, mas permanece em CPE porque compara poder empresarial em arranjos institucionais e regimes capitalistas distintos.",
