      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Growth Models and Financialization e a subarea pos-2008 que recoloca demanda agregada, exportacoes, consumo, divida, credito, financeirizacao e regimes macroeconomicos no centro da Comparative Political Economy. O DR ancora a virada em Crouch (2009), \"Privatised Keynesianism\", e Baccaro e Pontusson (2016), \"Rethinking Comparative Political Economy: The Growth Model Perspective\", porque esses textos deslocam o campo do foco exclusivo em supply-side institutions para motores macro de crescimento.\n\nKrippner (2011), *Capitalizing on Crisis*, explica a origem politica da financeirizacao, enquanto Hassel e Palier (2023), \"Same Trend, Different Paths\", conecta growth regimes e welfare regimes. A ficha funde growth models e financialization porque o DR mostra forte sobreposicao de textos e mecanismos: debt-led, consumption-led, export-led e finance-led growth pertencem ao mesmo giro macro-comparativo.",
      "ancoragem_base": -1.1,
