      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Democracy, Political Regimes and Growth pergunta se democracias crescem mais, menos ou de modo diferente de autocracias. O DR toma Przeworski e Limongi (1993), \"Political Regimes and Economic Growth\", e Barro (1996), \"Democracy and Growth\", como textos fundadores porque organizam o debate classico entre protecao de propriedade, redistribuicao, curto-prazismo e estabilidade institucional.\n\nA fase recente desloca a pergunta para canais indiretos como capital humano, bens publicos, reformas e accountability. Baum e Lake (2003), \"The Political Economy of Growth: Democracy and Human Capital\", enfatizam educacao e saude, enquanto Acemoglu, Naidu, Restrepo e Robinson (2019), \"Democracy Does Cause Growth\", reabre a agenda empirica com uma estrategia causal mais forte.",
