      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Political Instability, Conflict and Investment e a linha que trata risco politico, alternancia de governo, polarizacao e conflito distributivo como determinantes de investimento e crescimento. O DR destaca Alesina e Perotti (1996), \"Income Distribution, Political Instability, and Investment\", como paper fundador por conectar desigualdade, instabilidade sociopolitica e acumulacao.\n\nAlesina, Ozler, Roubini e Swagel (1996), \"Political Instability and Economic Growth\", generalizam o mecanismo para crescimento agregado: instabilidade aumenta incerteza de politica economica, encurta horizontes de governo e investidores e reduz investimento publico e privado. A literatura continua ativa porque dialoga com commitment, political risk, fragilidade estatal, polarizacao e crescimento baixo.",
