      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Voracity Effect and Common-Pool Growth estuda economias em que grupos politicamente fortes competem por rendas comuns, como recursos naturais, receitas fiscais ou windfalls externos. O DR destaca Lane e Tornell (1996), \"Power, Growth, and the Voracity Effect\", e Tornell e Lane (1999), \"The Voracity Effect\", como textos seminais porque mostram como choques positivos podem reduzir crescimento quando instituicoes fracas intensificam apropriacao improdutiva.\n\nA linha se sobrepoe a Resource Curse Political Economy, mas nao e duplicata: aqui o mecanismo canonico e common-pool politico, voracidade e disputa por rendas, enquanto resource curse e uma subarea mais ampla. Ross (2016), \"The Politics of the Resource Curse: A Review\", aparece no DR como survey recente que reinsere o mecanismo em debates sobre commodities, fiscalidade, captura e fragilidade estatal.",
      "ancoragem_base": 1,
      "ancoragem_analitica_auto": 0.916,
