      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Political Economy of Public Debt and Fiscal Policy estuda por que governos acumulam divida, distorcem gasto, atrasam ajustes ou escolhem politicas fiscais macroeconomicamente subotimas. O DR usa Alesina e Passalacqua (2016), \"The Political Economy of Government Debt\", como referencia canonica por sintetizar mecanismos eleitorais, distributivos, intergeracionais e institucionais por tras da divida publica.\n\nBattaglini e Coate (2008), \"A Dynamic Theory of Public Spending, Taxation, and Debt\", fornece a ponte formal com barganha legislativa dinamica, tributacao e gasto publico. A linha conversa diretamente com commitment, ciclos politico-fiscais, regras fiscais, austeridade, polarizacao e efeitos da divida sobre investimento e crescimento.",
