      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Identity Economics estuda como categorias sociais, papeis, pertencimento e normas de grupo entram na utilidade, nas crencas e nas escolhas economicas e politicas. Dentro da economia politica, ela ajuda a explicar voto, redistribuicao, conflito, nacionalismo, classe, polarizacao e apoio a politicas que nao derivam diretamente de interesse material estreito.\n\nAkerlof e Kranton (2000), \"Economics and Identity\", e citado no DR como o paper seminal que tornou identidade social tratavel no vocabulario microeconomico. O DR tambem liga a linha a Shayo (2009), que endogeneiza identidade em uma aplicacao a nacao, classe e redistribuicao, e a debates criticos sobre identidade como utilidade versus identidade como poder.",
