      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Beliefs and Redistributive Politics analisa como crencas sobre merito, sorte, justica, pobreza, mobilidade e responsabilidade individual moldam demanda por redistribuicao. A linha e comportamental-cultural porque preferencias redistributivas deixam de ser apenas funcao de renda e passam a depender de crencas sociais e moralmente carregadas.\n\nBenabou e Tirole (2006), \"Belief in a Just World and Redistributive Politics\", e mencionado no DR como formalizacao de crencas motivadas dentro da economia politica da redistribuicao. Alesina e Angeletos (2005), \"Fairness and Redistribution\", aparece como paper paralelo sobre como crencas de esforco e sorte podem sustentar diferentes equilibrios redistributivos.",
