      "descricao_o_que_e": "Social Capital and Trust estuda como confianca, capital social, cultura civica e normas de cooperacao afetam desempenho institucional, crescimento, provisao de bens publicos e estabilidade de arranjos politicos. Ela funciona como ponte entre cultura e instituicoes, porque trata valores e crencas sociais como mecanismos que sustentam enforcement informal e cooperacao.\n\nPutnam (1993), *Making Democracy Work: Civic Traditions in Modern Italy*, e citado no DR como referencia importante para cultura civica e desempenho institucional. A mesma passagem conecta essa agenda a Tabellini (2008/2010), Algan e Cahuc (2010) sobre inherited trust, e a capitulos recentes de New Institutional Economics sobre trust.",
