      "descricao_o_que_e": "Estuda como eleições, partidos e legislaturas transformam preferências e interesses em políticas públicas. Reúne modelos de competição por votos, entrada de candidatos, controle eleitoral dos governantes e negociação legislativa. Esses mecanismos se complementam: eleições selecionam representantes e podem discipliná-los, enquanto regras de agenda e votação condicionam as decisões posteriores. Persson e Tabellini organizam essa abordagem; Lindbeck–Weibull, Besley–Coate, Osborne–Slivinski e Baron–Ferejohn oferecem modelos distintos de partes do processo, com hipóteses próprias sobre informação, compromisso e participação.",
