      "confianca_ficha": "alta",
      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Representa políticas e pontos ideais dos eleitores em um espaço comum, permitindo estudar localização, diferenciação e convergência de plataformas. Hotelling fornece um antecedente na competição entre firmas; Black analisa agregação majoritária, e Downs desenvolve a aplicação à competição partidária. No modelo básico com dois candidatos, uma dimensão e compromisso com plataformas, a disputa por votos pode levar ao mediano. Número de candidatos, incerteza eleitoral e motivações programáticas mudam os incentivos. Em várias dimensões, a existência de equilíbrio exige condições adicionais.",
